drop policy if exists "catalog_public_read_published" on public.catalog_items;
create policy "catalog_public_read_published" on public.catalog_items for select to anon,authenticated using(is_published=true or (select auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists "catalog_admin_insert" on public.catalog_items;
create policy "catalog_admin_insert" on public.catalog_items for insert to authenticated with check((select auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists "catalog_admin_update" on public.catalog_items;
create policy "catalog_admin_update" on public.catalog_items for update to authenticated using((select auth.jwt()->'app_metadata'->>'role')='admin') with check((select auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists "catalog_admin_delete" on public.catalog_items;
create policy "catalog_admin_delete" on public.catalog_items for delete to authenticated using((select auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists "grants_read_own_or_admin" on public.access_grants;
