drop policy if exists "hub_assets_admin_update" on storage.objects;
create policy "hub_assets_admin_update" on storage.objects for update to authenticated using(bucket_id='titanichub-assets' and (select auth.jwt()->'app_metadata'->>'role')='admin') with check(bucket_id='titanichub-assets' and (select auth.jwt()->'app_metadata'->>'role')='admin');
